import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.BaseEntityBlock;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.RenderShape;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityTicker;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.block.state.properties.BooleanProperty;
import net.minecraft.world.level.material.MapColor;
import net.minecraft.world.level.material.PushReaction;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;
import org.jetbrains.annotations.Nullable;

public class QuestBarrierBlock extends BaseEntityBlock {
	public static final BooleanProperty OPEN = BooleanProperty.create("open");

	protected QuestBarrierBlock() {
		super(Properties.of()
				.mapColor(MapColor.COLOR_LIGHT_BLUE)
				.pushReaction(PushReaction.BLOCK)
				.noOcclusion()
				.isViewBlocking((blockState, blockGetter, blockPos) -> false)
				.isSuffocating((blockState, blockGetter, blockPos) -> false)
				.strength(-1, 6000000F)
				.lightLevel(blockState -> 3)
				.emissiveRendering((blockState, blockGetter, blockPos) -> true)
		);

		registerDefaultState(defaultBlockState().setValue(OPEN, false));
	}

	@Override
	protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) {
		builder.add(OPEN);
	}

	@Override
	public RenderShape getRenderShape(BlockState state) {
		return RenderShape.MODEL;
	}

	@Override
	public VoxelShape getCollisionShape(BlockState state, BlockGetter bg, BlockPos pos, CollisionContext ctx) {
		if (EntityHooks.fromCollision(ctx) instanceof Player player
				&& bg.getBlockEntity(pos) instanceof BarrierBlockEntity barrier
				&& barrier.isOpen(player)) {
			return Shapes.empty();
		}

		return super.getCollisionShape(state, bg, pos, ctx);
	}

	@Override
	public VoxelShape getVisualShape(BlockState state, BlockGetter blockGetter, BlockPos pos, CollisionContext ctx) {
		return Shapes.empty();
	}

	@Override
	@Environment(EnvType.CLIENT)
	public float getShadeBrightness(BlockState blockState, BlockGetter blockGetter, BlockPos blockPos) {
		return 1.0F;
	}

	@Override
	public boolean propagatesSkylightDown(BlockState state, BlockGetter bg, BlockPos pos) {
		return true;
	}

	@Override
	@Environment(EnvType.CLIENT)
	public boolean skipRendering(BlockState state, BlockState state2, Direction dir) {
		return state2.is(this) || super.skipRendering(state, state2, dir);
	}

	@Override
	public void setPlacedBy(Level level, BlockPos pos, BlockState state, @Nullable LivingEntity entity, ItemStack stack) {
		super.setPlacedBy(level, pos, state, entity, stack);

		if (!level.isClientSide() && stack.hasCustomHoverName() && level.getBlockEntity(pos) instanceof BarrierBlockEntity barrier) {
			barrier.update(stack.getHoverName().getString());
		}
	}

	@Nullable
	@Override
	public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level, BlockState blockState, BlockEntityType<T> blockEntityType) {
		return (level != null && level.isClientSide()) ? BarrierBlockEntity::tick : null;
	}

	@Nullable
	@Override
	public BlockEntity newBlockEntity(BlockPos blockPos, BlockState blockState) {
		return new QuestBarrierBlockEntity(blockPos, blockState);
	}
}

package dev.ftb.mods.ftbquests.block.entity;

import dev.ftb.mods.ftbquests.client.FTBQuestsClient;
import net.minecraft.core.BlockPos;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

import static dev.ftb.mods.ftbquests.block.QuestBarrierBlock.OPEN;

public interface BarrierBlockEntity {
	void update(String s);

	boolean isOpen(Player player);

	static void tick(Level level, BlockPos blockPos, BlockState blockState, BlockEntity blockEntity) {
		if (blockEntity instanceof BarrierBlockEntity barrier) {
			if (level.isClientSide && FTBQuestsClient.isClientDataLoaded() && level.getGameTime() % 5L == 0L) {
				boolean completed = barrier.isOpen(FTBQuestsClient.getClientPlayer());

				if (completed != blockState.getValue(OPEN)) {
					level.setBlock(blockPos, blockState.setValue(OPEN, completed), 2 | 8);
					blockEntity.setChanged();
				}
			}
		}
	}
}

package dev.ftb.mods.ftbquests.block.entity;

import dev.architectury.hooks.level.entity.PlayerHooks;
import dev.ftb.mods.ftbquests.quest.QuestObjectBase;
import dev.ftb.mods.ftbquests.quest.ServerQuestFile;
import dev.ftb.mods.ftbquests.quest.TeamData;
import dev.ftb.mods.ftbquests.util.ProgressChange;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;

public class DetectorBlockEntity extends BlockEntity {
	private long objectId = 0L;
	private int radius = 8;

	public DetectorBlockEntity(BlockPos blockPos, BlockState blockState) {
		super(FTBQuestsBlockEntities.DETECTOR.get(), blockPos, blockState);
	}

	@Override
	public void load(CompoundTag tag) {
		super.load(tag);

		objectId = QuestObjectBase.parseCodeString(tag.getString("Object"));
		radius = tag.getInt("Radius");
	}

	@Override
	public void saveAdditional(CompoundTag tag) {
		tag.putString("Object", QuestObjectBase.getCodeString(objectId));
		tag.putInt("Radius", radius);
	}

	public void update(String idStr) {
		objectId = ServerQuestFile.INSTANCE.getID(idStr);
	}

	private static boolean isRealPlayer(ServerPlayer player) {
		return !PlayerHooks.isFake(player);
	}

	public void onPowered(Level level, BlockPos pos) {
		QuestObjectBase qo = ServerQuestFile.INSTANCE.getBase(objectId);
		if (qo != null) {
			AABB box = new AABB(pos).inflate(radius);
			for (ServerPlayer player : level.getEntitiesOfClass(ServerPlayer.class, box, DetectorBlockEntity::isRealPlayer)) {
				TeamData data = ServerQuestFile.INSTANCE.getOrCreateTeamData(player);
				qo.forceProgressRaw(data, new ProgressChange(ServerQuestFile.INSTANCE, qo, player.getUUID()).setReset(false).withNotifications());
			}
		}
	}
}

package dev.ftb.mods.ftbquests.block.entity;

import dev.ftb.mods.ftbquests.api.FTBQuestsAPI;
import dev.ftb.mods.ftbquests.quest.BaseQuestFile;
